import { useState } from "react";
import { Container, Box, TextField, Button, Typography } from "@mui/material";

function Torneo() {

  const [formData, setFormData] = useState({
    teamName: "",
    referente: "",
    email: "",
    telefono: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log(formData);
    alert("Iscrizione inviata!");
  };

  return (
    <Container maxWidth="md">

      {/* intestazione */}
      <Box sx={{ mt: 6, mb: 6 }}>

        <Typography variant="h3" gutterBottom>
          Torneo Seriana Cobras
        </Typography>

        <Typography variant="body1">
          Inserisci qui la descrizione del torneo.
          Puoi spiegare formato, categorie, data, luogo e premi.
        </Typography>

      </Box>

      {/* form */}
      <Box
        component="form"
        onSubmit={handleSubmit}
        sx={{
          display: "flex",
          flexDirection: "column",
          gap: 3,
          mb: 8
        }}
      >

        <TextField
          label="Nome squadra"
          name="teamName"
          onChange={handleChange}
          required
          fullWidth
        />

        <TextField
          label="Nome referente"
          name="referente"
          onChange={handleChange}
          required
          fullWidth
        />

        <TextField
          label="Email"
          name="email"
          type="email"
          onChange={handleChange}
          required
          fullWidth
        />

        <TextField
          label="Telefono"
          name="telefono"
          onChange={handleChange}
          fullWidth
        />

        <Button
          type="submit"
          variant="contained"
          size="large"
        >
          Iscrivi la squadra
        </Button>

      </Box>

    </Container>
  );
}

export default Torneo;
